<template>
 <ion-page><ion-header><ion-toolbar><ion-buttons slot="start"><ion-menu-button /></ion-buttons><ion-title>{{ translate('Zone mappings') }}</ion-title><ion-buttons slot="end"><ion-button @click="edit()"><ion-icon slot="start" :icon="addOutline" />{{ translate('Add mapping') }}</ion-button></ion-buttons></ion-toolbar></ion-header>
 <ion-content><main class="zone-content">
  <h1>{{ translate('ZIP service zones') }}</h1><p>{{ translate('Look up the shipping zone and ground transit time from an origin ZIP to a destination ZIP.') }}</p>
  <ion-card><ion-card-content><div class="zone-filters"><ion-input fill="outline" label-placement="stacked" :label="translate('Origin ZIP')" placeholder="18101" v-model="origin" inputmode="numeric" :maxlength="5" /><ion-input fill="outline" label-placement="stacked" :label="translate('Destination ZIP')" placeholder="10001" v-model="destination" inputmode="numeric" :maxlength="5" /><ion-select fill="outline" label-placement="stacked" :label="translate('Carrier')" v-model="carrier" interface="popover"><ion-select-option value="">{{ translate('All carriers') }}</ion-select-option><ion-select-option value="FedEx">FedEx</ion-select-option><ion-select-option value="UPS">UPS</ion-select-option></ion-select><ion-button fill="clear" @click="origin='';destination='';carrier=''">{{ translate('Clear') }}</ion-button></div></ion-card-content></ion-card>
  <ion-card><ion-card-header><ion-card-title>{{ translate('Zone mappings') }} · {{ rows.length }}</ion-card-title><ion-card-subtitle>{{ translate('Exact ZIP matches take precedence over prefixes for the same origin and carrier.') }}</ion-card-subtitle></ion-card-header>
   <div class="zone-table-wrap"><table><thead><tr><th>{{ translate('Origin ZIP') }}</th><th>{{ translate('Destination') }}</th><th>{{ translate('Carrier') }}</th><th>{{ translate('Zone') }}</th><th>{{ translate('Ground transit') }}</th><th>{{ translate('Actions') }}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><strong>{{ row.origin }}</strong></td><td>{{ row.destination }}{{ row.matchType==='prefix' ? '*' : '' }}<p>{{ translate(row.matchType==='prefix' ? 'ZIP prefix' : 'Exact ZIP') }}</p></td><td>{{ row.carrier }}</td><td>{{ row.zone }}</td><td>{{ row.days }} {{ translate(row.days===1 ? 'day' : 'days') }}</td><td><ion-button :aria-label="translate('Edit') + ' ' + row.origin + ' → ' + row.destination + ' ' + row.carrier" fill="clear" @click="edit(row)">{{ translate('Edit') }}</ion-button><ion-button :aria-label="translate('Delete') + ' ' + row.origin + ' → ' + row.destination + ' ' + row.carrier" fill="clear" color="danger" @click="remove(row)">{{ translate('Delete') }}</ion-button></td></tr></tbody></table></div>
   <ion-card-content v-if="!rows.length"><h2>{{ translate('No matching zone') }}</h2><p>{{ translate('Try a different ZIP pair or add a mapping for this lane.') }}</p></ion-card-content>
  </ion-card>
 </main></ion-content></ion-page>
</template>
<script setup lang="ts">
import { computed,ref } from 'vue';
import { IonPage,IonHeader,IonToolbar,IonTitle,IonButtons,IonButton,IonMenuButton,IonIcon,IonContent,IonCard,IonCardContent,IonCardHeader,IonCardTitle,IonCardSubtitle,IonInput,IonSelect,IonSelectOption,IonNote,modalController,alertController } from '@ionic/vue';
import { addOutline } from 'ionicons/icons';
import { translate } from '@common';
import { useZoneMappingsStore,type ZoneMapping } from '@/store/zoneMappings';
import ZoneMappingModal from '@/components/zones/ZoneMappingModal.vue';
const store=useZoneMappingsStore();const origin=ref('');const destination=ref('');const carrier=ref('');
const rows=computed(()=>{const matching=store.mappings.filter(r=>(!origin.value || r.origin.startsWith(origin.value)) && (!carrier.value || r.carrier===carrier.value) && (!destination.value || (r.matchType==='prefix' ? destination.value.startsWith(r.destination) : r.destination.startsWith(destination.value))));return matching.filter(r=>!destination.value || destination.value.length!==5 || r.matchType==='exact' || !matching.some(exact=>exact.matchType==='exact' && exact.destination===destination.value && exact.origin===r.origin && exact.carrier===r.carrier));});
async function edit(mapping?:ZoneMapping){const modal=await modalController.create({component:ZoneMappingModal,componentProps:{mapping}});await modal.present();}
async function remove(row:ZoneMapping){const alert=await alertController.create({header:translate('Delete zone mapping?'),message:row.origin+' → '+row.destination+' · '+row.carrier,buttons:[{text:translate('Cancel'),role:'cancel'},{text:translate('Delete'),role:'destructive',handler:()=>store.remove(row.id)}]});await alert.present();}
</script>
<style scoped>.zone-content{max-width:1200px;margin:24px auto;padding:0 24px}.zone-filters{display:grid;grid-template-columns:1fr 1fr 1fr auto;align-items:center;gap:16px}.zone-table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:14px 20px;border-bottom:1px solid var(--ion-color-light-shade);white-space:nowrap}th{font-size:12px;color:var(--ion-color-medium)}td p{margin:4px 0 0;font-size:12px;color:var(--ion-color-medium)}@media(max-width:700px){.zone-filters{grid-template-columns:1fr 1fr}.zone-content{padding:0 8px}}</style>
